CREATE DATABASE IF NOT EXISTS kalam CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kalam;
SET NAMES utf8mb4;

DROP TABLE IF EXISTS tentativa_questoes;
DROP TABLE IF EXISTS tentativas;
DROP TABLE IF EXISTS progresso;
DROP TABLE IF EXISTS questoes;
DROP TABLE IF EXISTS aulas;
DROP TABLE IF EXISTS modulos;
DROP TABLE IF EXISTS usuarios;

CREATE TABLE usuarios (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nome VARCHAR(100) NOT NULL,
  email VARCHAR(150) NOT NULL UNIQUE,
  senha_hash VARCHAR(255) NOT NULL,
  tipo ENUM('aluno','admin') NOT NULL DEFAULT 'aluno',
  criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE modulos (
  id TINYINT PRIMARY KEY,
  titulo VARCHAR(120) NOT NULL,
  descricao VARCHAR(255) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE aulas (
  id INT PRIMARY KEY,
  modulo_id TINYINT NOT NULL,
  titulo VARCHAR(150) NOT NULL,
  conteudo MEDIUMTEXT NOT NULL,
  video_url VARCHAR(255) NULL,
  doc_titulo VARCHAR(150) NOT NULL,
  doc_resumo TEXT NOT NULL,
  FOREIGN KEY (modulo_id) REFERENCES modulos(id)
) ENGINE=InnoDB;

CREATE TABLE progresso (
  usuario_id INT NOT NULL,
  aula_id INT NOT NULL,
  concluida_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (usuario_id, aula_id),
  FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,
  FOREIGN KEY (aula_id) REFERENCES aulas(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE questoes (
  id INT AUTO_INCREMENT PRIMARY KEY,
  tema VARCHAR(30) NOT NULL,
  enunciado TEXT NOT NULL,
  alt_a TEXT NOT NULL,
  alt_b TEXT NOT NULL,
  alt_c TEXT NULL,
  alt_d TEXT NULL,
  alt_e TEXT NULL,
  correta CHAR(1) NOT NULL
) ENGINE=InnoDB;

CREATE TABLE tentativas (
  id INT AUTO_INCREMENT PRIMARY KEY,
  usuario_id INT NOT NULL,
  iniciada_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  finalizada_em DATETIME NULL,
  acertos TINYINT NULL,
  FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE tentativa_questoes (
  id INT AUTO_INCREMENT PRIMARY KEY,
  tentativa_id INT NOT NULL,
  questao_id INT NULL,
  ordem TINYINT NOT NULL,
  resposta CHAR(1) NULL,
  correta TINYINT(1) NULL,
  FOREIGN KEY (tentativa_id) REFERENCES tentativas(id) ON DELETE CASCADE,
  FOREIGN KEY (questao_id) REFERENCES questoes(id) ON DELETE SET NULL
) ENGINE=InnoDB;


-- Módulos
INSERT INTO modulos (id, titulo, descricao) VALUES
  (1, 'Ideologias em choque', 'As duas formas de organizar a economia que disputavam o mundo antes de 1917.'),
  (2, 'O fim do czarismo', 'A Rússia dos czares, a guerra e os meses entre fevereiro e abril de 1917.'),
  (3, 'O poder bolchevique', 'A tomada do poder, a paz com a Alemanha e a guerra civil.'),
  (4, 'A URSS de Lenin a Stalin', 'NEP, disputa pela sucessão, planos quinquenais e o contraste com o capitalismo em crise.'),
  (5, 'Da Guerra Fria ao fim da URSS', 'A divisão do mundo em dois blocos e o colapso soviético.');

-- Aulas
INSERT INTO aulas (id, modulo_id, titulo, conteudo, video_url, doc_titulo, doc_resumo) VALUES
  (1, 1, 'O capitalismo e suas fases', '<p>Em 1776, Adam Smith publicou <em>A Riqueza das Nações</em> para explicar por que o comércio e a manufatura cresciam tanto na Inglaterra. Sua resposta foi o interesse próprio (<em>self-interest</em>): o padeiro não assa pão por bondade, e sim porque quer vender. Quando cada um busca o próprio ganho, argumentava Smith, a concorrência acaba regulando preços, salários e produção, como se uma mão invisível do mercado organizasse tudo. Daí a defesa de um Estado pequeno e do liberalismo econômico.</p>
<p>O capitalismo passou por etapas. O capitalismo comercial (séculos XV a XVIII) nasceu com a expansão marítima europeia, o mercantilismo e o lucro do comércio colonial. Os Estados buscavam balança comercial favorável, e a burguesia enriquecia com a acumulação primitiva de capital.</p>
<p>O capitalismo industrial começou com a Revolução Industrial, na Inglaterra do século XVIII. A fábrica substituiu a oficina artesanal, e carvão, tecidos, navios e siderurgia moveram a economia; mais tarde vieram petróleo, eletricidade, indústria química e motores. Nessa fase o trabalho passou a ser vendido como mercadoria: quem não tinha terra nem máquinas só podia oferecer suas horas por um salário. É a ideia do historiador Karl Polanyi, para quem trabalho, terra e dinheiro precisaram ser organizados para a venda no mercado.</p>
<p>O capitalismo financeiro, ou monopolista, domina do fim do século XIX em diante. Bancos e grandes corporações passam a controlar a economia, surgem monopólios e oligopólios, e as potências industriais disputam mercados e matérias-primas. Henry Ford representa o auge da fase industrial: a linha de montagem semiautomática, usada no Modelo T, barateou a produção e aumentou a oferta de produtos. Esse modelo é o fordismo.</p>
<p>A disputa por mercados levou ao imperialismo (ou neocolonialismo) dos séculos XIX e XX, quando potências europeias repartiram a África e a Ásia. Para justificar a dominação, usavam o darwinismo social, que dizia haver povos superiores, e a ideia de missão civilizadora, conhecida como o fardo do homem branco.</p>
<p>A partir dos anos 1970 e 1980, o neoliberalismo recuperou ideias de Smith: privatização de estatais, livre circulação de capitais, abertura da economia às multinacionais e combate ao protecionismo. Forte intervenção do Estado, ao contrário, é o oposto do que o neoliberalismo defende.</p>
<p class="fixar"><strong>Para fixar.</strong> A ordem das fases é comercial, industrial e financeiro. Burguesia e colônias vêm primeiro, depois as fábricas, depois os bancos e as multinacionais.</p>', NULL, 'A Riqueza das Nações (1776)', 'Livro de Adam Smith que defende a divisão do trabalho, a livre concorrência e o interesse próprio como motores do crescimento econômico. É dele a imagem da mão invisível, usada para explicar como o mercado se ajusta sem direção do Estado.'),
  (2, 1, 'Marx, luta de classes e comunismo', '<p>Karl Marx (1818 a 1883) e Friedrich Engels viram nas fábricas inglesas o que a teoria de Smith deixava de fora. De um lado estavam os burgueses, donos de fábricas e máquinas; do outro, os proletários, que só tinham a própria força de trabalho. Para eles, a história das sociedades é a história da luta de classes. No <em>Manifesto Comunista</em>, de 1848, a tese aparece em forma de panfleto político.</p>
<p>Marx se inspirou na dialética de Hegel (1770 a 1831), mas deu a ela uma base material. O motor da história são as condições de produção: quando as forças de produção se desenvolvem e esbarram nas relações que as seguram, o conflito leva à revolução e a um novo sistema.</p>
<p>Em <em>O Capital</em> (1867), Marx explica a mais-valia. O operário produz, em sua jornada, mais valor do que recebe de salário. A diferença, apropriada pelo capitalista sob a forma de lucro, é a mais-valia, e é nela que Marx vê a exploração, mesmo quando o salário é pago como combinado. Não se trata do lucro do comerciante, de um aumento de salário nem de um imposto.</p>
<p>Para Marx, o capitalismo seria superado por uma revolução do proletariado. Viria primeiro uma fase de transição, o socialismo, com a ditadura do proletariado: a classe operária usaria o Estado para desmontar a propriedade privada dos meios de produção. Só depois surgiria o comunismo, sem classes e sem Estado.</p>
<p>Aqui está a diferença para os anarquistas, como Pierre-Joseph Proudhon e Mikhail Bakunin. Eles queriam eliminar o Estado imediatamente, sem etapa de transição, porque o viam apenas como instrumento de dominação. Os marxistas achavam que o Estado ainda seria necessário no socialismo e só desapareceria no fim do processo.</p>
<p>Lenin adaptaria essa teoria, décadas depois, a um país de maioria camponesa, a Rússia. As próximas aulas mostram como.</p>
<p class="fixar"><strong>Para fixar.</strong> Anarquismo: fim imediato do Estado. Marxismo: socialismo como etapa, depois fim do Estado e das classes.</p>', NULL, 'Manifesto do Partido Comunista (1848)', 'Escrito por Marx e Engels a pedido da Liga dos Comunistas. Apresenta a luta de classes como chave para entender a história, prevê a queda da burguesia e termina chamando os trabalhadores de todos os países a se unirem.'),
  (3, 2, 'Rússia czarista: atraso, repressão e guerra', '<p>No início do século XX, a Rússia era um império enorme e uma das últimas monarquias absolutas da Europa. O czar Nicolau II concentrava o poder e governava com uma polícia política e o apoio da Igreja ortodoxa. A imensa maioria da população era camponesa. A servidão tinha sido abolida em 1861, mas muitos camponeses seguiam endividados e com pouca terra.</p>
<p>A industrialização veio tarde, com capital estrangeiro, e se concentrou em poucas cidades, como São Petersburgo e Moscou. Havia poucos operários, mas reunidos em fábricas enormes, com jornadas longas e salários baixos, o que facilitava a organização política.</p>
<p>Na oposição havia os liberais (Cadetes), os socialistas revolucionários, ligados aos camponeses, e os marxistas do Partido Operário Social-Democrata Russo. Em 1903 este partido se dividiu. Os bolcheviques (maioria), liderados por Lenin, defendiam um partido de revolucionários profissionais. Os mencheviques (minoria) preferiam um partido mais amplo e uma revolução feita em etapas, aliada à burguesia liberal.</p>
<p>A derrota na guerra contra o Japão (1904 a 1905) expôs a fraqueza do regime. Em 22 de janeiro de 1905, tropas atiraram contra uma marcha pacífica que levava uma petição ao czar: foi o Domingo Sangrento. Greves e motins se espalharam, e surgiram os primeiros sovietes. Nicolau II cedeu com o Manifesto de Outubro, que criou a Duma (um parlamento) e prometeu liberdades civis, mas manteve poder para dissolvê-la. Lenin chamaria 1905 de ensaio geral da revolução.</p>
<p>Em 1914, a Rússia entrou na Primeira Guerra Mundial ao lado da Entente, formada por Reino Unido e França. O exército era mal equipado e acumulou derrotas. Em 1917 o quadro era de deserções, motins de soldados, greves, falta de comida e de combustível nas grandes cidades, queda da produção, salários corroídos e desemprego. Esse desgaste levou à Revolução Russa de 1917, e não o contrário: a Rússia já estava na guerra desde 1914.</p>
<p class="fixar"><strong>Para fixar.</strong> Bolchevique quer dizer maioria, menchevique quer dizer minoria. A guerra e a fome foram o estopim de 1917.</p>', NULL, 'Manifesto de Outubro (1905)', 'Decreto de Nicolau II publicado em 30 de outubro de 1905 (17 de outubro no calendário russo da época). Prometia liberdades civis e a criação de uma Duma com poder legislativo. Foi uma concessão feita sob pressão de greves, e o czar manteve amplos poderes.'),
  (4, 2, '1917: a queda do czar e as Teses de Abril', '<p>Em fevereiro de 1917 (março pelo nosso calendário), greves por pão em Petrogrado, a capital, cresceram até virar levante. Os soldados mandados reprimir os protestos passaram para o lado dos manifestantes. Nicolau II abdicou, e o império czarista acabou. Foi a Revolução de Fevereiro.</p>
<p>O poder ficou dividido. O Governo Provisório, formado por liberais e depois chefiado por Aleksandr Kerensky, queria manter a Rússia na guerra e adiar a reforma agrária. Ao lado dele funcionava o Soviete de Petrogrado, conselho de operários e soldados que tinha o apoio real das ruas e dos quartéis. Os historiadores chamam essa situação de dualidade de poderes.</p>
<p>Em abril, Lenin voltou do exílio na Suíça e apresentou as Teses de Abril. Ele rompia com qualquer apoio ao Governo Provisório e propunha a saída da Rússia da guerra, a entrega da terra aos camponeses e a transferência de todo o poder aos sovietes. O lema era "Paz, Pão e Terra". Até parte do Partido Bolchevique estranhou, pois a teoria marxista tradicional previa que a Rússia passaria antes por uma fase de república burguesa.</p>
<p>Dois erros aparecem com frequência nas provas. O lema não foi de Stalin, e sim dos bolcheviques liderados por Lenin, e servia para atrair camponeses e soldados, não para aliar-se aos mencheviques. E quem manteve a Rússia na guerra foi o governo de Kerensky; quem a tirou dela foram os bolcheviques, depois, com o Tratado de Brest-Litovsk.</p>
<p class="fixar"><strong>Para fixar.</strong> Teses de Abril: fim da guerra, terra aos camponeses, poder aos sovietes e nenhum apoio ao Governo Provisório.</p>', 'https://www.youtube.com/watch?v=6RawMVE-mOU', 'Teses de Abril (1917)', 'Conjunto de dez teses apresentado por Lenin em abril de 1917, logo depois de voltar a Petrogrado. Negava apoio ao Governo Provisório, pedia o fim da guerra, o confisco das grandes propriedades e o poder dos sovietes.'),
  (5, 3, 'A Revolução de Outubro e o poder dos sovietes', '<p>O soviete era um conselho formado por delegados eleitos de operários, soldados e camponeses. Surgiu em 1905 e voltou em 1917 como órgão de poder local. Ao longo do ano, os bolcheviques conquistaram a maioria nos sovietes de Petrogrado e de Moscou, porque defendiam o fim da guerra e a distribuição de terras, enquanto o Governo Provisório perdia apoio ao insistir na guerra. O soviete não era sindicato, nem milícia, nem órgão burocrático.</p>
<p>Na noite de 24 para 25 de outubro de 1917 pelo calendário russo (6 para 7 de novembro no nosso), o Comitê Militar Revolucionário do Soviete de Petrogrado, organizado por Leon Trotsky, ocupou pontos estratégicos da capital e tomou o Palácio de Inverno, sede do governo. Kerensky fugiu. O Congresso dos Sovietes aprovou então um governo bolchevique, o Conselho dos Comissários do Povo, presidido por Lenin.</p>
<p>As primeiras medidas foram o Decreto sobre a Paz, que propunha o fim da guerra, e o Decreto sobre a Terra, que aboliu a grande propriedade rural sem indenização e entregou a terra aos camponeses. Nos meses seguintes, o governo instituiu o controle operário nas fábricas e nacionalizou os bancos, em dezembro de 1917.</p>
<p>Em janeiro de 1918, os bolcheviques dissolveram a Assembleia Constituinte, na qual eram minoria. A decisão foi criticada por liberais e por outros socialistas e mostrou que o novo regime não pretendia dividir o poder.</p>
<p class="fixar"><strong>Para fixar.</strong> Soviete é conselho de operários, soldados e camponeses. Outubro de 1917 no calendário russo é novembro no nosso.</p>', NULL, 'Decretos sobre a Paz e sobre a Terra (1917)', 'Aprovados pelo Congresso dos Sovietes logo depois da tomada do poder. O primeiro convidava todos os países em guerra a negociar uma paz sem anexações. O segundo extinguia a propriedade privada da terra dos grandes proprietários.'),
  (6, 3, 'Brest-Litovsk, guerra civil e Comunismo de Guerra', '<p>Para cumprir a promessa de paz, o governo bolchevique negociou com a Alemanha e seus aliados. Em março de 1918, assinou o Tratado de Brest-Litovsk, que tirou a Rússia da Primeira Guerra Mundial, mas a um custo alto: a perda de grandes áreas no oeste, como a Polônia, os países bálticos e a Ucrânia. Para Lenin, o tratado era duro, porém necessário para salvar a revolução.</p>
<p>A paz externa trouxe a guerra interna. Entre 1918 e 1921, o Exército Vermelho, organizado por Trotsky, enfrentou os Brancos, grupo heterogêneo de monarquistas, liberais e oficiais czaristas. Potências da Entente, entre elas Reino Unido, França, Estados Unidos e Japão, enviaram tropas e recursos aos Brancos, porque temiam a expansão do bolchevismo.</p>
<p>Desde 1919, os países vencedores da Primeira Guerra também tentaram formar um cordão sanitário, uma barreira de países anticomunistas no Leste Europeu apoiada na Polônia e na Romênia. Ninguém monta uma barreira contra algo irrelevante ou já derrotado. Por isso, a existência do cordão sanitário indica que a revolução socialista tinha se firmado na Rússia soviética.</p>
<p>Para sustentar a guerra, o governo adotou o Comunismo de Guerra, de 1918 a 1921: nacionalização das indústrias, requisição forçada de grãos dos camponeses, fim do comércio privado e racionamento. O sistema abasteceu o exército, mas a produção desabou e houve fome. Em março de 1921, os marinheiros da base naval de Kronstadt, antigos apoiadores dos bolcheviques, se revoltaram contra o regime. A revolta foi esmagada, mas convenceu Lenin de que era preciso mudar o rumo.</p>
<p class="fixar"><strong>Para fixar.</strong> Brest-Litovsk (1918) tirou a Rússia da guerra. O Comunismo de Guerra nacionalizou as indústrias. Kronstadt (1921) levou à NEP.</p>', NULL, 'Tratado de Brest-Litovsk (1918)', 'Acordo de março de 1918 entre a Rússia soviética e as Potências Centrais, entre elas Alemanha e Áustria-Hungria. Encerrou a participação russa na guerra com grandes perdas territoriais. Foi anulado depois que a Alemanha perdeu a guerra, em novembro de 1918.'),
  (7, 4, 'NEP, sucessão de Lenin e a disputa entre Stalin e Trotsky', '<p>Em 1921, Lenin lançou a Nova Política Econômica (NEP), um recuo calculado. A requisição de grãos acabou e deu lugar a um imposto fixo. Os camponeses puderam vender o excedente no mercado, e o pequeno comércio e a pequena indústria voltaram à iniciativa privada. O Estado manteve o controle dos bancos, da grande indústria e do comércio exterior. Ou seja, não houve coletivização forçada nem privatização geral: era uma economia mista, que recuperou boa parte da produção perdida na guerra civil.</p>
<p>Em dezembro de 1922 foi proclamada a União das Repúblicas Socialistas Soviéticas (URSS). Lenin, doente, morreu em janeiro de 1924. Stalin, secretário-geral do Partido desde 1922, e Trotsky, organizador do Exército Vermelho, passaram a disputar a sucessão. A divergência não era só pessoal.</p>
<p>Stalin defendia o socialismo em um só país: construir o socialismo dentro da URSS, sem esperar revoluções no exterior. Trotsky sustentava a revolução permanente. Para ele, um país atrasado e isolado não manteria o socialismo por muito tempo, que dependia de a revolução se estender a outros países, sobretudo aos industrializados. Stalin venceu. Trotsky foi expulso do Partido em 1927, exilado em 1929 e assassinado no México, em 1940, por um agente stalinista.</p>
<p>A Internacional Comunista (Comintern, ou Terceira Internacional), criada por Lenin em 1919, coordenava os partidos comunistas do mundo. Em 1928, seu VI Congresso mudou de linha: em vez de tratar os social-democratas como aliados, passou a vê-los como adversários, chegando a chamá-los de social-fascistas. Por isso, o item que afirma o contrário é falso.</p>
<p class="fixar"><strong>Para fixar.</strong> NEP: mercado liberado no pequeno, Estado no grande. Stalin: socialismo em um só país. Trotsky: revolução permanente.</p>', NULL, 'O Testamento de Lenin (1922 e 1923)', 'Cartas ditadas por Lenin quando já estava doente. Ele critica os principais dirigentes e, em um adendo, sugere afastar Stalin do cargo de secretário-geral por considerá-lo rude demais. O texto só veio a público na URSS décadas depois.'),
  (8, 4, 'Stalinismo, Planos Quinquenais e o New Deal', '<p>Com Stalin no poder, a NEP foi abandonada. Em 1928 começou o primeiro Plano Quinquenal. O objetivo era acelerar a industrialização, com ênfase na indústria pesada (aço, carvão, máquinas e energia), por meio do planejamento estatal: um órgão central, o Gosplan, fixava metas obrigatórias de produção. No campo veio a coletivização das terras. Os camponeses foram obrigados a entrar em fazendas coletivas, e quem resistiu, como os kulaks (camponeses mais ricos), foi preso, deportado ou morto. A desorganização provocou uma fome terrível no início dos anos 1930, que matou milhões de pessoas, principalmente na Ucrânia e no Cazaquistão.</p>
<p>A indústria cresceu depressa e a URSS virou uma potência industrial, mas à custa de repressão. Nos Grandes Expurgos de 1936 a 1938, dirigentes do Partido, militares e cidadãos comuns foram acusados de traição, presos ou fuzilados, e o sistema de campos de trabalho forçado, o Gulag, se expandiu.</p>
<p>O Estado também passou a controlar a cultura. A arte oficial virou o realismo socialista, de composições didáticas e simples, que exaltavam o trabalho, a combatividade e a consciência social do povo soviético. Estilos considerados burgueses ou abstratos foram perseguidos.</p>
<p>Enquanto isso, o capitalismo enfrentava a crise de 1929. A quebra da Bolsa de Nova York, em outubro daquele ano, levou bancos à falência e milhões de pessoas ao desemprego. A resposta dos Estados Unidos foi o New Deal (1933), de Franklin Roosevelt, que se aproximava das ideias do economista John Maynard Keynes: mais intervenção do Estado, obras públicas para gerar empregos e maior regulação do sistema financeiro.</p>
<p>O New Deal não era socialismo, pois manteve a propriedade privada e o mercado. Mas rompeu com a confiança de Smith na mão invisível como única reguladora: para Keynes, numa crise, o Estado precisa agir. A URSS, de economia planificada e pouco ligada ao mercado externo, sentiu menos o efeito direto da crise, o que deu prestígio ao planejamento aos olhos de alguns contemporâneos.</p>
<p class="fixar"><strong>Para fixar.</strong> Planos Quinquenais: indústria pesada, planejamento estatal e coletivização. New Deal: Estado mais presente, mas dentro do capitalismo.</p>', NULL, 'Primeiro Plano Quinquenal (1928 a 1932)', 'Programa econômico que fixou metas obrigatórias de produção para a indústria e a agricultura soviéticas, com prioridade para a indústria pesada. Stalin o declarou cumprido em quatro anos e três meses, antes do prazo previsto.'),
  (9, 5, 'Guerra Fria: cortina de ferro, contenção e corrida armamentista', '<p>Em 1945, o Exército Vermelho tinha avançado sobre o Leste Europeu na luta contra a Alemanha nazista. A URSS aproveitou a presença militar para instalar governos comunistas aliados em países como Polônia, Hungria, Romênia, Bulgária e Tchecoslováquia. Em 1946, num discurso nos Estados Unidos, o ex-primeiro-ministro britânico Winston Churchill disse que uma cortina de ferro descia sobre o continente, dividindo a Europa entre o Leste, sob influência soviética, e o Oeste, de orientação capitalista.</p>
<p>Os Estados Unidos responderam com a política de contenção. Em março de 1947, a Doutrina Truman prometeu ajuda a países ameaçados pelo comunismo, como Grécia e Turquia. Em junho do mesmo ano foi anunciado o Plano Marshall, que destinou bilhões de dólares à reconstrução das economias da Europa Ocidental e também ajudava a evitar que a miséria fortalecesse partidos comunistas.</p>
<p>A URSS recusou o plano e pressionou os aliados a recusá-lo. Criou em 1949 o Comecon, organização de cooperação econômica do bloco socialista, e em 1955 o Pacto de Varsóvia, a aliança militar do Leste, resposta à OTAN, formada pelo lado ocidental em 1949.</p>
<p>Em agosto de 1949, a URSS testou sua primeira bomba atômica e acabou com o monopólio nuclear que os Estados Unidos tinham desde 1945. A corrida armamentista se intensificou e surgiu o chamado equilíbrio do terror: nenhum dos lados atacava, porque a resposta destruiria os dois.</p>
<p>A disputa chegou ao espaço. Em 1957, os soviéticos lançaram o Sputnik 1, o primeiro satélite artificial, e em 1961 Yuri Gagarin foi o primeiro ser humano a orbitar a Terra. Os Estados Unidos reagiram criando a NASA, em 1958, e investindo mais em ciência e educação. Os feitos soviéticos abalaram a confiança americana na própria superioridade tecnológica, e o mesmo foguete que levava satélites também podia levar mísseis.</p>
<p class="fixar"><strong>Para fixar.</strong> Truman e Marshall: contenção do comunismo. Comecon: economia do bloco socialista. Pacto de Varsóvia: aliança militar do bloco socialista.</p>', NULL, 'Discurso da cortina de ferro (1946)', 'Discurso de Churchill em Fulton, nos Estados Unidos, em 5 de março de 1946. Ele já não era primeiro-ministro. Afirmou que uma cortina de ferro dividia a Europa e defendeu uma aliança entre britânicos e americanos diante da expansão soviética.'),
  (10, 5, 'Muro de Berlim, Cuba, Afeganistão e o fim da URSS', '<p>A Alemanha derrotada foi dividida em quatro zonas de ocupação, e Berlim também. Entre 1948 e 1949, os soviéticos bloquearam o acesso terrestre a Berlim Ocidental, e os aliados abasteceram a cidade por uma ponte aérea. Em 1949 surgiram duas Alemanhas, a Federal (capitalista) e a Democrática (socialista). Durante anos, milhões de alemães orientais fugiram para o Ocidente por Berlim, o que drenava mão de obra qualificada e desgastava a imagem do regime. Em agosto de 1961, a Alemanha Oriental, com apoio da URSS, ergueu o Muro de Berlim para conter essa emigração.</p>
<p>Em 1962, os Estados Unidos descobriram bases de mísseis soviéticos em Cuba, governada por Fidel Castro desde 1959 e aliada da URSS. O presidente John Kennedy impôs um bloqueio naval à ilha, e durante cerca de duas semanas o mundo temeu uma guerra nuclear. A crise terminou em acordo: a URSS retirou os mísseis, os Estados Unidos se comprometeram a não invadir Cuba e, em sigilo, retiraram os mísseis que mantinham na Turquia.</p>
<p>Em dezembro de 1979, a URSS invadiu o Afeganistão para sustentar um governo comunista aliado, ameaçado por guerrilheiros islâmicos, os mujahidin. Os Estados Unidos apoiaram os guerrilheiros. A guerra durou cerca de dez anos, as tropas soviéticas só saíram em 1989, e o desgaste material e político contribuiu para a crise interna da URSS.</p>
<p>Em 1985, Mikhail Gorbatchev assumiu a liderança soviética em meio a uma economia estagnada e a gastos militares altos. Lançou a Perestroika (reestruturação), que descentralizou a economia e abriu espaço limitado para a iniciativa privada, e a Glasnost (transparência), que ampliou a liberdade de imprensa e o debate político. As reformas não restabeleceram os planos quinquenais de Stalin e não foram impostas pelos Estados Unidos.</p>
<p>Em novembro de 1989 caiu o Muro de Berlim, os governos comunistas do Leste Europeu caíram em seguida, e em dezembro de 1991 a URSS foi dissolvida.</p>
<p>Um bom debate sobre o tema pesa os dois lados. A URSS industrializou o país e ampliou o acesso à educação e à saúde, mas tinha partido único, censura e repressão. O capitalismo gerou riqueza e avanços tecnológicos, mas também crises como a de 1929 e muita desigualdade. As perguntas sobre o papel do Estado e do mercado seguem em pauta, por exemplo nas discussões sobre privatizações e sobre a regulação do sistema financeiro.</p>
<p class="fixar"><strong>Para fixar.</strong> Perestroika: reestruturação econômica. Glasnost: transparência política. O Muro foi erguido em 1961 para conter a fuga de alemães orientais.</p>', NULL, 'Perestroika (1987)', 'Livro em que Gorbatchev expõe as razões das reformas e defende a reestruturação do sistema soviético sem abandonar o socialismo. Foi publicado em 1987, dois anos depois de ele chegar ao poder.');

-- Banco de 30 questões 
INSERT INTO questoes (tema, enunciado, alt_a, alt_b, alt_c, alt_d, alt_e, correta) VALUES
  ('Revolução Russa', '(UFMG) Com relação ao processo revolucionário russo que culminou com a tomada do poder pelos bolcheviques em 1917, pode-se afirmar que:', 'Na fase denominada Comunismo de Guerra, uma das primeiras medidas tomadas por Lenin foi a nacionalização dos bancos e das principais indústrias.', 'O governo provisório liderado por Kerensky, tão logo assumiu o poder retirou a Rússia da Guerra através do Tratado de Brest-Litovsky', 'O lema “Paz, Terra e Pão” adotado por Stalin, foi fundamental para a mobilização do campesinato e seu engajamento na luta ao lado dos mencheviques.', 'Na guerra civil entre brancos e vermelhos, os brancos receberam auxílio de mercenários de toda a Europa, recrutados por países capitalistas.', 'Na fase da NEP (Nova Política Econômica) houve estatização definitiva de todas as indústrias bem como a proibição da entrada de técnicos estrangeiros.', 'a'),
  ('Revolução Russa', '(UEFS) Uma política foi sendo aos poucos colocada em prática, desde 1919, pelos países vencedores na Primeira Guerra Mundial: não intervir, porém conter o bolchevismo. Formar uma “barragem contínua”, apoiando-se no exército polonês e no exército romeno. Era o primeiro esboço do mais tarde chamado “cordão sanitário”.
(Jean-Jacques Becker. O Tratado de Versalhes, 2011. Adaptado.)
O historiador alude, implicitamente,', 'à irrelevância da revolução russa nas relações internacionais.', 'à ausência de plano no combate dos capitalistas ao socialismo soviético.', 'à aliança entre nações capitalistas e forças czaristas no combate ao socialismo.', 'à defesa pelo Ocidente das liberdades democráticas nos estados socialistas.', 'à consolidação da revolução socialista na Rússia soviética.', 'e'),
  ('Revolução Russa', '(PUC-Campinas)
"... derrotas na guerra, deserções, motins militares contra os superiores, greves nas fábricas, falta de gêneros alimentícios e combustíveis nas principais cidades, queda na produção, aviltamento dos salários, incapacidade governamental, desemprego e crescente miséria das massas."
O quadro descrito no texto conduziu à:', 'crescente insatisfação da burguesia russa em relação ao governo do Czar.', 'entrada da Rússia na I Grande Guerra.', 'rebelião Boxer na China em 1900.', 'Segunda Guerra Mundial em 1939.', 'Revolução Russa em 1917.', 'e'),
  ('Revolução Russa', '(PUC/SP) O Estado Soviético, formado após a Revolução Russa, cuidou de expurgar da cultura desse país toda e qualquer manifestação artística que estivesse, no entendimento das autoridades, associada ao chamado "espírito burguês". Foi criada, então, uma política cultural que decretava como arte oficial apenas as expressões que servissem de estímulo para a ideologia do proletariado.
Dessa forma, foi consagrado um estilo conhecido por:', 'expressionismo soviético - que, através de uma orientação estética intimista, procurava expor a "alma inquieta dos povos eslavos", que passaram a integrar a União das Repúblicas Socialistas Soviéticas.', 'abstracionismo proletário - que, através da decomposição geométrica do real, exprimia a "ordenação sincrônica da sociedade comunista".', 'realismo socialista - que, através de composições didáticas, esteticamente simplificadas, procurava enaltecer a "combatividade, a capacidade de trabalho e a consciência social" do povo soviético.', 'romantismo comunista - que, através de um figurativismo apenas sugestivo, procurava realizar a "idealização do munique", o camponês russo típico, como representante das raízes culturais russas.', 'concretismo operário - que, através de uma concepção criadora autônoma - não resultante de modelos -, utilizava elementos visuais e táteis, com o objetivo de mostrar a "prevalência do concreto sobre o abstrato"- ideia básica no materialismo dialético.', 'c'),
  ('Revolução Russa', '(FURG/RS) No movimento revolucionário russo de 1917, o soviet consistia em:', 'uma organização sindical socialista.', 'uma organização militar estalinista.', 'um comitê formado por camponeses rebeldes, operários e soldados.', 'um conselho burocrático popular.', 'uma milícia formada por cossacos.', 'c'),
  ('Comunismo', 'Karl Marx (1818-1883) foi o responsável por formular uma teoria que visava explicar a história analisando o embate travado entre as diferentes classes sociais. Esse modelo, inspirado principalmente na dialética de Hegel (1770-1831), tinha como fundamento:', 'o conflito travado entre as forças estáticas de produção (tese) e as forças dinâmicas de produção (antítese), que proporcionavam um maior aprimoramento das forças de produção, revolucionando o sistema.', 'o ideal de história cíclica e que não poderia haver um fim específico, já que os conflitos sociais tornavam a existir praticamente iguais.', 'a ideia de que a sociedade era imutável e sempre haveria, de um lado, os donos dos meios de produção e, do outro, os donos da força de trabalho.', 'a ideia de luta de classes envolvendo os defensores da ideologia socialista e os defensores do comunismo.', 'o ideal de história finalista, em que os donos dos meios de produção entregam, por seu inteiro consentimento, o controle aos proletariados.', 'a'),
  ('Comunismo', 'O Anarquismo, teoria revolucionária surgida no século XIX e que teve em Pierre-Joseph Proudhon (1809-1865) um dos seus principais teóricos, prega a eliminação do Estado, pois este seria apenas um instrumento de dominação das classes mais abastadas. Entretanto, no Comunismo Marxista, a eliminação do Estado também ocorreria. Sendo assim, assinale a alternativa que apresenta a diferença basilar entre essas duas teorias.', 'Enquanto os anarquistas pregavam a eliminação imediata do Estado, os comunistas defendiam que haveria o socialismo, uma etapa que antecederia a eliminação do Estado.', 'Enquanto os anarquistas viam a eliminação do Estado como uma etapa a ser cumprida, os comunistas entendiam esta como um fim único.', 'No comunismo, haveria a ditadura do proletariado como uma etapa da evolução da história humana.', 'A diferença entre essas duas era que o anarquismo era uma teoria de direita, enquanto o comunismo era de esquerda.', 'Enquanto o comunismo defendia a eliminação do sistema capitalista, o anarquismo defendia a manutenção do capitalismo e apenas a eliminação do Estado.', 'a'),
  ('Comunismo', 'No século passado, o fascismo e o comunismo foram correntes ideológicas presentes na política de muitos países. A respeito dessas correntes, julgue o item a seguir.
O VI Congresso do Comintern, a Terceira Internacional, de 1928, classificou os social-democratas como principais aliados do proletariado na luta contra o imperialismo.', 'Certo', 'Errado', NULL, NULL, NULL, 'b'),
  ('Capitalismo', '"Não é da benevolência do açougueiro, do cervejeiro e do padeiro que esperamos o nosso jantar, mas da consideração que ele tem pelos próprios interesses. Apelamos não à humanidade, mas ao amor-próprio, e nunca falamos de nossas necessidades, mas das vantagens que eles podem obter."
Adam Smith, A Riqueza das Nações
Adam Smith foi um economista britânico que estruturou os princípios fundamentais do capitalismo. Segundo sua doutrina o "interesse próprio" (self-interest) seria o motor pelo qual o desenvolvimento social e econômico ocorreria.
Segundo a doutrina proposta por Adam Smith os aspectos econômicos, sociais e políticos seriam controlados pela:', 'intervenção do Estado', 'mão invisível do mercado', 'autoridade do Estado', 'liberdade ilimitada dos cidadãos', NULL, 'b'),
  ('Capitalismo', 'O capitalismo, ao longo do tempo, atravessou diversas fases marcadas por:
I. Balança comercial favorável, surgimento e ascensão da burguesia.
II. Revolução no modo de produção e desenvolvimento do setor fabril.
III. Centralidade nos bancos e nas grandes corporações multinacionais.
Essas três fases descritas acima representam, respectivamente, as características principais do:', 'capitalismo financeiro, capitalismo industrial e capitalismo comercial.', 'capitalismo comercial, capitalismo monopolista e capitalismo informacional.', 'capitalismo comercial, capitalismo industrial e capitalismo financeiro.', 'capitalismo financeiro, capitalismo informacional e capitalismo comercial.', NULL, 'c'),
  ('Capitalismo', 'O modelo de produção desenvolvido por Henry Ford representou um avanço no modo produtivo e o apogeu do capitalismo industrial, que possibilitou o início de uma nova fase do capitalismo, monopolista.
Esse processo, chamado de fordismo, é caracterizado por:', 'Organização de artesãos em cooperativas, produção customizada e destinada a consumidores de alto poder aquisitivo.', 'Desenvolvimento de planos quinquenais, produção destinada a suprir as necessidades da população e o controle estatal da indústria.', 'Aplicação de linhas de montagens semiautomáticas, redução dos custos de produção e aumento da oferta de produtos.', 'Automação do processo produtivo, extinção da estocagem e produção sob encomenda.', NULL, 'c'),
  ('Capitalismo', 'O neoliberalismo é uma das principais tendências do capitalismo contemporâneo. De acordo com as características do neoliberalismo, considere as afirmações abaixo como verdadeiras (V) ou falsas (F):
I. Privatização de empresas estatais
II. Livre circulação de capitais internacionais
III. Abertura econômica para a entrada de empresas multinacionais
IV. Forte intervenção do Estado na economia
V. Adoção de medidas contra o protecionismo econômico
Qual a alternativa correta?', 'V, F, V, F, V.', 'V, V, V, F, V.', 'F, V, V, V, F.', 'V, V, F, F, V.', NULL, 'b'),
  ('Capitalismo', '(Enem 2016) Quanto mais complicada se tornou a produção industrial, mais numerosos passaram a ser os elementos da indústria que exigiam garantia de fornecimento. Três deles eram de importância fundamental: o trabalho, a terra e o dinheiro. Numa sociedade comercial, esse fornecimento só poderia ser organizado de uma forma: tornando-os disponíveis à compra. Agora eles tinham que ser organizados para a venda no mercado. Isso estava de acordo com a exigência de um sistema de mercado. Sabemos que em um sistema como esse, os lucros só podem ser assegurados se se garante a autorregulação por meio de mercados competitivos interdependentes.
POLANYI, K. A grande transformação: as origens de nossa época. Rio de Janeiro: Campus, 2000 (adaptado).
A consequência do processo de transformação socioeconômica abordado no texto é a:', 'expansão das terras comunais.', 'limitação do mercado como meio de especulação.', 'consolidação da força de trabalho como mercadoria.', 'diminuição do comércio como efeito da industrialização.', 'adequação do dinheiro como elemento padrão das transações.', 'c'),
  ('Capitalismo', 'A política imperialista consistia na busca, principalmente, de novos mercados consumidores para os países industrializados e foi assim que vários países da África e da Ásia sofreram com a prática da neocolonização nos séculos XIX e XX. Portanto, sobre a justificativa construída pelas potências europeias para invadir as nações do continente africano e asiático correto dizer que:', 'As potências europeias justificavam a invasão nos países periféricos afirmando que essa ação contribuiria para o desenvolvimento industrial e que incentivaria a adoção de um regime socialista nos países asiáticos', 'As principais alegações utilizadas na prática do Imperialismo foram as teorias darwinistas que defendiam a superioridade cultural dos países europeus, sendo eles os países que levariam o progresso e o desenvolvimento social para os países da África e da Ásia através da missão civilizadora.', 'Uma das justificativas era que os europeus aprenderiam técnicas industriais com os africanos e asiáticos, o que acarretaria no desenvolvimento econômico e científico dos países desenvolvidos.', 'O fardo do homem branco era uma das legitimações europeias durante a política imperialista. Esse fardo consistia numa missão que contribuiria para o desenvolvimento industrial dos países africanos e asiáticos, gerando assim o crescimento da burguesia local, fazendo com que os países não desenvolvidos tivessem suas próprias indústrias.', NULL, 'b'),
  ('Revolução Russa', 'Em abril de 1917, ao retornar do exílio, Lenin apresentou as chamadas “Teses de Abril”, que orientaram a atuação dos bolcheviques nos meses seguintes. Entre as propostas centrais desse documento, destacava-se:', 'o apoio ao Governo Provisório, para que a Rússia concluísse a guerra ao lado da Entente.', 'a manutenção das grandes propriedades rurais nas mãos da nobreza até o fim do conflito.', 'a saída da Rússia da guerra, a entrega da terra aos camponeses e a transferência do poder aos sovietes.', 'a restauração da monarquia, após a abdicação de Nicolau II.', 'a formação de uma coalizão com liberais e mencheviques para consolidar uma república parlamentar.', 'c'),
  ('Revolução Russa', 'Após o Comunismo de Guerra (1918-1921), a crise econômica e a revolta dos marinheiros de Kronstadt levaram Lenin a adotar, em 1921, a Nova Política Econômica (NEP). Essa política caracterizou-se por:', 'coletivização forçada de todas as propriedades rurais e proibição de qualquer forma de comércio privado.', 'liberdade para o pequeno comércio e a pequena propriedade camponesa, mantendo o Estado no controle dos bancos, da grande indústria e do comércio exterior.', 'privatização geral das indústrias e devolução das fábricas aos antigos proprietários, com abertura total ao capital estrangeiro.', 'adoção dos Planos Quinquenais, com metas obrigatórias de produção voltadas à indústria pesada.', 'substituição da moeda pela distribuição estatal de mercadorias, sem qualquer forma de mercado.', 'b'),
  ('Revolução Russa', 'Com a consolidação de Stalin no poder, a União Soviética lançou, a partir de 1928, os Planos Quinquenais. O principal objetivo dessa política era:', 'ampliar o espaço da iniciativa privada, nos moldes da NEP, para atrair investimentos estrangeiros.', 'priorizar a produção de bens de consumo leves para exportação aos mercados capitalistas.', 'fortalecer a pequena propriedade camponesa, com crédito e liberdade de comércio dos excedentes.', 'acelerar a industrialização, com ênfase na indústria pesada, por meio do planejamento estatal e da coletivização das terras.', 'promover a exportação imediata da revolução socialista para a Europa Ocidental.', 'd'),
  ('Revolução Russa', 'Após a morte de Lenin, em 1924, Stalin e Trotsky protagonizaram uma disputa pela direção do Partido e do Estado soviético, que refletia também divergências teóricas. Enquanto Stalin defendia a tese do “socialismo em um só país”, Trotsky sustentava:', 'a manutenção da NEP por tempo indeterminado, sem qualquer planejamento estatal.', 'a aproximação com as potências capitalistas para garantir investimentos na URSS.', 'a substituição do Partido Comunista por um sistema multipartidário.', 'a extinção imediata do Estado e a divisão da terra em comunas autônomas, nos moldes anarquistas.', 'a tese da revolução permanente: o socialismo só se sustentaria se a revolução se estendesse a outros países.', 'e'),
  ('Comunismo', 'Na obra O Capital, Karl Marx analisou o funcionamento do modo de produção capitalista e formulou o conceito de “mais-valia”. Segundo essa análise, a mais-valia corresponde:', 'ao valor produzido pelo trabalhador além do necessário à sua subsistência, apropriado pelo capitalista sob a forma de lucro.', 'ao lucro do comerciante que compra mercadorias a baixo preço nas colônias e as revende mais caro na metrópole.', 'ao aumento do salário do operário em decorrência da elevação da produtividade da fábrica.', 'ao imposto cobrado pelo Estado sobre os bens produzidos pelas indústrias.', 'à valorização das ações de uma empresa em períodos de expansão econômica.', 'a'),
  ('Capitalismo', 'Após a crise de 1929, que levou à quebra da Bolsa de Nova York e ao desemprego em massa, o presidente norte-americano Franklin Roosevelt lançou o New Deal, programa que se aproximava das ideias do economista John Maynard Keynes. Essa política caracterizou-se por:', 'defender a ausência do Estado na economia, para que a “mão invisível” restabelecesse o equilíbrio do mercado.', 'promover a estatização completa dos meios de produção e a abolição da propriedade privada.', 'reduzir os gastos públicos e privatizar empresas estatais para conter a inflação.', 'ampliar a intervenção do Estado, com obras públicas, geração de empregos e maior regulação do sistema financeiro.', 'suspender os direitos trabalhistas para reduzir os custos de produção e estimular as exportações.', 'd'),
  ('Guerra Fria', 'Ao final da Segunda Guerra Mundial, o avanço do Exército Vermelho sobre o Leste Europeu permitiu à URSS ampliar sua zona de influência, com a instalação de governos comunistas aliados em vários países. Em 1946, em discurso nos Estados Unidos, o ex-primeiro-ministro britânico Winston Churchill usou a expressão “cortina de ferro” para designar:', 'o sistema de radares e mísseis instalado pelos EUA na fronteira da URSS.', 'o bloqueio econômico imposto pelas potências aliadas à Alemanha derrotada.', 'a divisão política e ideológica da Europa entre o Leste, sob influência soviética, e o Oeste, de orientação capitalista.', 'a fronteira militar entre as zonas de ocupação britânica e francesa na Alemanha.', 'o acordo secreto entre Stalin e Hitler para repartir o território polonês.', 'c'),
  ('Guerra Fria', 'Em 1947, os Estados Unidos lançaram a Doutrina Truman e o Plano Marshall. Esses programas tinham como objetivo principal:', 'financiar a expansão do socialismo na Europa Oriental por meio de empréstimos ao governo soviético.', 'conter o avanço do comunismo na Europa, com ajuda militar e econômica a países aliados e à reconstrução de suas economias.', 'formar uma aliança militar entre EUA e URSS contra os resquícios do nazifascismo.', 'estabelecer a divisão da Alemanha em quatro zonas de ocupação, definida pelos vencedores da guerra.', 'apoiar os movimentos de independência da Ásia e da África contra as potências coloniais europeias.', 'b'),
  ('Guerra Fria', 'No contexto da Guerra Fria, o bloco liderado pela URSS criou o Comecon (1949) e o Pacto de Varsóvia (1955). Esses organismos eram, respectivamente:', 'uma aliança militar e um banco internacional de desenvolvimento do bloco capitalista.', 'um órgão de cooperação econômica do bloco capitalista e uma aliança militar do bloco socialista.', 'tratados de desarmamento nuclear assinados entre os EUA e a URSS.', 'organismos da ONU criados para mediar os conflitos entre as superpotências.', 'uma organização de cooperação econômica e uma aliança militar do bloco socialista.', 'e'),
  ('Guerra Fria', 'Em agosto de 1949, a URSS realizou com sucesso o teste de sua primeira bomba atômica, pondo fim ao monopólio nuclear que os Estados Unidos detinham desde 1945. Esse acontecimento contribuiu para:', 'intensificar a corrida armamentista e consolidar o chamado “equilíbrio do terror”, baseado na ameaça de destruição mútua.', 'encerrar a Guerra Fria, pois as duas superpotências passaram a cooperar na área nuclear.', 'levar à retirada das tropas soviéticas dos países do Leste Europeu.', 'isolar a URSS, que foi expulsa do Conselho de Segurança da ONU.', 'reduzir os gastos militares dos EUA, que deixaram de se sentir ameaçados.', 'a'),
  ('Guerra Fria', 'Em outubro de 1957, a URSS colocou em órbita o Sputnik 1, primeiro satélite artificial da Terra, e, em abril de 1961, enviou ao espaço Yuri Gagarin, o primeiro ser humano a orbitar o planeta. Do ponto de vista da Guerra Fria, esses feitos soviéticos:', 'resultaram de um programa conjunto de cooperação científica entre a URSS e os EUA.', 'levaram os EUA a abandonar os investimentos em programas espaciais e a priorizar a diplomacia.', 'abalaram a confiança norte-americana em sua superioridade tecnológica e estimularam a criação da NASA, em 1958, e maiores investimentos em ciência e educação.', 'foram realizados com o apoio técnico direto da China, aliada da URSS na corrida espacial.', 'provaram que o bloco capitalista era incapaz de desenvolver foguetes e mísseis balísticos.', 'c'),
  ('Guerra Fria', 'Em agosto de 1961, o governo da Alemanha Oriental, com o apoio da URSS, iniciou a construção do Muro de Berlim. A principal motivação dessa medida foi:', 'evitar uma invasão da Alemanha Oriental por tropas da OTAN.', 'cumprir uma determinação da ONU para dividir a cidade entre as quatro potências ocupantes.', 'separar o setor soviético dos setores ocupados por Polônia e Tchecoslováquia.', 'conter a emigração em massa de alemães orientais para Berlim Ocidental, que drenava mão de obra qualificada e desgastava a imagem do regime.', 'responder ao embargo comercial imposto pelos EUA à URSS após o Bloqueio de Berlim.', 'd'),
  ('Guerra Fria', 'Em outubro de 1962, a descoberta de bases de lançamento de mísseis soviéticos em Cuba levou o mundo à beira de um conflito nuclear. O presidente norte-americano John Kennedy respondeu com um bloqueio naval à ilha, e a crise foi resolvida com:', 'a invasão de Cuba pelos EUA e a queda do governo de Fidel Castro.', 'um acordo em que a URSS retirou os mísseis de Cuba, os EUA se comprometeram a não invadir a ilha e, de forma reservada, retiraram mísseis instalados na Turquia.', 'a vitória militar soviética no Caribe, que forçou o fim do bloqueio naval sem nenhuma contrapartida.', 'a intervenção de tropas da ONU, que ocuparam a ilha e desmontaram as bases.', 'a decisão de Cuba de romper com a URSS e de se alinhar ao bloco capitalista.', 'b'),
  ('Guerra Fria', 'Em dezembro de 1979, tropas soviéticas invadiram o Afeganistão para sustentar um governo comunista aliado, ameaçado por guerrilheiros islâmicos. Entre as consequências dessa intervenção, destaca-se:', 'a rápida vitória do Exército Vermelho, que consolidou um regime comunista estável no país.', 'a aproximação definitiva entre EUA e URSS, com o fim da corrida armamentista.', 'a retirada imediata das tropas soviéticas, após resolução do Conselho de Segurança da ONU, em 1980.', 'o apoio dos EUA ao governo afegão pró-soviético, contra os guerrilheiros mujahidin.', 'um conflito de cerca de dez anos, com apoio dos EUA aos mujahidin, que desgastou a URSS e contribuiu para sua crise interna.', 'e'),
  ('Guerra Fria', 'Em 1985, Mikhail Gorbatchev assumiu a liderança da União Soviética em meio a uma grave crise econômica e a elevados gastos militares. Sobre as reformas que promoveu, assinale a alternativa correta:', 'A Perestroika propunha reestruturar a economia, com descentralização e abertura limitada à iniciativa privada, enquanto a Glasnost ampliava a transparência política e a liberdade de imprensa.', 'A Perestroika restabeleceu os Planos Quinquenais da era Stalin, e a Glasnost reforçou a censura sobre a imprensa e a oposição.', 'A Glasnost extinguiu o Partido Comunista já em 1985 e implantou, de imediato, uma economia de mercado plena.', 'As reformas foram impostas pelos EUA como condição para a concessão de ajuda econômica à URSS, nos moldes do Plano Marshall.', 'As reformas limitaram-se à política externa, sem qualquer efeito sobre a economia e a sociedade soviéticas.', 'a'),
  ('Revolução Russa', 'Em março de 1918, o governo bolchevique assinou o Tratado de Brest-Litovsk com as Potências Centrais. Esse acordo:', 'retirou a Rússia da Primeira Guerra Mundial, ao custo de grandes perdas territoriais.', 'selou a aliança entre a Rússia soviética e a Entente contra a Alemanha.', 'encerrou a guerra civil entre brancos e vermelhos.', 'restaurou a monarquia de Nicolau II.', 'criou a Nova Política Econômica (NEP).', 'a');
